<script>
const dom = {
root: document.getElementById('approot'),
messages: document.getElementById('chatmessages'),
input: document.getElementById('chatinput'),
sendBtn: document.getElementById('sendbtn'),
sidebar: document.getElementById('sidebarpanel'),
overlay: document.getElementById('sidebaroverlay'),
history: document.getElementById('historycontainer'),
attachmentTrigger: document.getElementById('attachmenttrigger'),
attachmentMenu: document.getElementById('attachmentmenu'),
fileChips: document.getElementById('filechips'),
searchToggleUi: document.getElementById('searchtoggleui'),
searchToggleKnob: document.getElementById('searchtoggleknob'),
imgInput: document.getElementById('hiddenimageinput'),
fileInput: document.getElementById('hiddenfileinput'),
menuToggleBtn: document.getElementById('menutogglebtn'),
newChatBtn: document.getElementById('newchatbtn'),
toggleSearchBtn: document.getElementById('togglesearchbtn'),
uploadImageBtn: document.getElementById('uploadimagebtn'),
uploadFileBtn: document.getElementById('uploadfilebtn'),
inputContainerWrapper: document.getElementById('inputcontainerwrapper')
};

function loadHistoryFromStorage() {
try {
var raw = localStorage.getItem('chat_history');
if (!raw) return [];
var parsed = JSON.parse(raw);
if (Array.isArray(parsed)) return parsed;
return [];
} catch (e) {
return [];
}
}

var idCounter = 0;
function generateId() {
idCounter++;
return 'id' + Date.now().toString(36) + '' + idCounter.toString(36) + '' + Math.random().toString(36).substring(2, 10);
}

var state = {
currentThread: [],
history: loadHistoryFromStorage(),
isSidebarOpen: false,
isAttachmentMenuOpen: false,
isSearchEnabled: false,
selectedFiles: [],
isGenerating: false,
codeWidgetStates: {},
generationAbortController: null,
userScrolledUp: false,
responseIndex: 0
};

function saveHistoryToStorage() {
try {
var json = JSON.stringify(state.history);
if (json.length > 4  1024  1024) {
while (state.history.length > 1 && JSON.stringify(state.history).length > 4  1024  1024) {
state.history.shift();
}
json = JSON.stringify(state.history);
}
localStorage.setItem('chat_history', json);
} catch (e) {
if (state.history.length > 1) {
state.history.shift();
saveHistoryToStorage();
}
}
}

function escapeHtml(text) {
var div = document.createElement('div');
div.appendChild(document.createTextNode(text));
return div.innerHTML;
}

function toggleSidebar(force) {
state.isSidebarOpen = force !== undefined ? force : !state.isSidebarOpen;
if (state.isSidebarOpen) {
dom.sidebar.classList.remove('translatexfull');
dom.overlay.classList.remove('pointereventsnone');
dom.overlay.classList.remove('opacity0');
dom.overlay.classList.add('opacity100');
} else {
dom.sidebar.classList.add('translatexfull');
dom.overlay.classList.add('opacity0');
dom.overlay.classList.remove('opacity100');
dom.overlay.classList.add('pointereventsnone');
}
}

function closeAttachmentMenu() {
if (!state.isAttachmentMenuOpen) return;
state.isAttachmentMenuOpen = false;
dom.attachmentMenu.classList.add('opacity0', 'scale95', 'translatey2', 'pointereventsnone');
dom.attachmentMenu.classList.remove('opacity100', 'scale100', 'translatey0');
}

function openAttachmentMenu() {
state.isAttachmentMenuOpen = true;
dom.attachmentMenu.classList.remove('opacity0', 'scale95', 'translatey2', 'pointereventsnone');
dom.attachmentMenu.classList.add('opacity100', 'scale100', 'translatey0');
}

function toggleAttachmentMenu() {
if (state.isAttachmentMenuOpen) {
closeAttachmentMenu();
} else {
openAttachmentMenu();
}
}

function toggleSearch() {
state.isSearchEnabled = !state.isSearchEnabled;
if (state.isSearchEnabled) {
dom.searchToggleUi.className = 'w7 h4 roundedfull relative transitioncolors duration200 bg[007AFF]';
dom.searchToggleKnob.classList.add('translatex3');
} else {
dom.searchToggleUi.className = 'w7 h4 roundedfull relative transitioncolors duration200 bgwhite/10';
dom.searchToggleKnob.classList.remove('translatex3');
}
closeAttachmentMenu();
}

function addFiles(files, isImage) {
Array.from(files).forEach(function(f) {
var fileObj = {
id: generateId(),
name: f.name,
size: f.size,
type: f.type,
file: f,
isImage: isImage || (f.type && f.type.startsWith('image/'))
};
if (fileObj.isImage && f.type && f.type.startsWith('image/')) {
fileObj.isImage = true;
} else if (isImage) {
fileObj.isImage = true;
} else {
fileObj.isImage = false;
}
state.selectedFiles.push(fileObj);
});
renderFileChips();
updateSendButton();
}

function removeFile(fileId) {
state.selectedFiles = state.selectedFiles.filter(function(f) { return f.id !== fileId; });
renderFileChips();
updateSendButton();
}

function renderFileChips() {
dom.fileChips.innerHTML = '';
state.selectedFiles.forEach(function(fileObj) {
