} else {
iconSvg = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="007AFF" strokewidth="2"><path d="M15 2H6a2 2 0 0 02 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 22V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/></svg>';
