import os
import json
import base64
import mimetypes
from io import BytesIO
from contextlib import asynccontextmanager
from typing import Any, Dict, List, Optional, Tuple, Union

import httpx
from fastapi import FastAPI, Request, UploadFile, HTTPException
from fastapi.responses import HTMLResponse, JSONResponse, StreamingResponse


BIGMODEL_BASE_URL = "https://open.bigmodel.cn/api/paas/v4"
BIGMODEL_CHAT_COMPLETIONS_URL = f"{BIGMODEL_BASE_URL}/chat/completions"
DEFAULT_TEXT_MODEL = "glm-5"
DEFAULT_VISION_MODEL = "glm-4.6v-flash"

MAX_SINGLE_UPLOAD_BYTES = 25 * 1024 * 1024
MAX_TOTAL_UPLOAD_BYTES = 60 * 1024 * 1024
MAX_EXTRACTED_TEXT_CHARS = 220000

INDEX_HTML_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "index.html")


def get_api_key() -> str:
    candidates = [
        "bigmodel.cr",
        "BIGMODEL_CR",
        "BIGMODEL_API_KEY",
        "ZAI_API_KEY",
        "ZHIPUAI_API_KEY",
        "ZHIPU_API_KEY",
    ]
    for k in candidates:
        v = os.getenv(k)
        if v and v.strip():
            return v.strip()
    raise RuntimeError("Missing BigModel API key in environment (Replit Secrets).")


def _as_bool(v: Any) -> bool:
    if v is None:
        return False
    if isinstance(v, bool):
        return v
    s = str(v).strip().lower()
    return s in ("1", "true", "yes", "y", "on", "enabled")


def _clamp_int(v: Any, default: int, min_v: int, max_v: int) -> int:
    try:
        iv = int(v)
    except Exception:
        iv = default
    if iv < min_v:
        return min_v
    if iv > max_v:
        return max_v
    return iv


def _clamp_float(v: Any, default: float, min_v: float, max_v: float) -> float:
    try:
        fv = float(v)
    except Exception:
        fv = default
    if fv < min_v:
        return min_v
    if fv > max_v:
        return max_v
    return fv


def _guess_mime(filename: str, declared: Optional[str]) -> str:
    if declared and "/" in declared:
        return declared
    mt, _ = mimetypes.guess_type(filename or "")
    return mt or "application/octet-stream"


def _safe_decode_text(data: bytes) -> str:
    for enc in ("utf-8", "utf-16", "utf-32", "gb18030", "big5", "latin-1"):
        try:
            return data.decode(enc)
        except Exception:
            pass
    return data.decode("utf-8", errors="replace")


def _truncate_text(s: str, max_chars: int) -> str:
    if len(s) <= max_chars:
        return s
    return s[:max_chars]


def _extract_pdf_text(data: bytes) -> str:
    try:
        from pypdf import PdfReader
    except Exception:
        return ""
    try:
        reader = PdfReader(BytesIO(data))
        parts: List[str] = []
        for p in reader.pages:
            try:
                t = p.extract_text() or ""
            except Exception:
                t = ""
            if t:
                parts.append(t)
            if sum(len(x) for x in parts) >= MAX_EXTRACTED_TEXT_CHARS:
                break
        return "\n\n".join(parts)
    except Exception:
        return ""


def _extract_docx_text(data: bytes) -> str:
    try:
        import docx
    except Exception:
        return ""
    try:
        d = docx.Document(BytesIO(data))
        parts = []
        for p in d.paragraphs:
            if p.text:
                parts.append(p.text)
            if sum(len(x) for x in parts) >= MAX_EXTRACTED_TEXT_CHARS:
                break
        return "\n".join(parts)
    except Exception:
        return ""


async def _read_upload_bytes(up: UploadFile, limit: int) -> bytes:
    buf = await up.read()
    if len(buf) > limit:
        raise HTTPException(status_code=413, detail=f"File too large: {up.filename}")
    return buf


def _normalize_messages(messages: Any) -> List[Dict[str, Any]]:
    if messages is None:
        return []
    if not isinstance(messages, list):
        raise HTTPException(status_code=400, detail="messages must be a list")
    out: List[Dict[str, Any]] = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        role = m.get("role")
        content = m.get("content")
        if role not in ("system", "user", "assistant", "tool"):
            continue
        if content is None:
            continue
        out.append({"role": role, "content": content})
    return out


def _last_user_text(messages: List[Dict[str, Any]]) -> str:
    for m in reversed(messages):
        if m.get("role") == "user":
            c = m.get("content")
            if isinstance(c, str):
                return c
            if isinstance(c, list):
                texts = []
                for part in c:
                    if isinstance(part, dict) and part.get("type") in ("text", "input_text"):
                        t = part.get("text")
                        if isinstance(t, str) and t.strip():
                            texts.append(t.strip())
                if texts:
                    return "\n".join(texts)
    return ""


def _build_user_content_with_attachments(
    user_text: str,
    extracted_file_texts: List[Tuple[str, str]],
    images_data_urls: List[Tuple[str, str]],
) -> Union[str, List[Dict[str, Any]]]:
    text_blocks: List[str] = []
    if user_text and user_text.strip():
        text_blocks.append(user_text.strip())

    if extracted_file_texts:
        file_sections = []
        for name, txt in extracted_file_texts:
            t = txt.strip()
            if not t:
                continue
            file_sections.append(f"FÁJL: {name}\n\n{t}")
        if file_sections:
            text_blocks.append("\n\n".join(file_sections))

    merged_text = "\n\n".join(text_blocks).strip()

    if images_data_urls:
        content_parts: List[Dict[str, Any]] = []
        if merged_text:
            content_parts.append({"type": "text", "text": merged_text})
        for _name, data_url in images_data_urls:
            content_parts.append({"type": "image_url", "image_url": {"url": data_url}})
        return content_parts

    return merged_text


async def _prepare_payload_from_request(
    request: Request,
) -> Tuple[Dict[str, Any], bool]:
    content_type = (request.headers.get("content-type") or "").lower()

    if "multipart/form-data" in content_type:
        form = await request.form()
        model = (form.get("model") or "").strip() or DEFAULT_TEXT_MODEL
        stream = _as_bool(form.get("stream"))
        web_search = _as_bool(form.get("web_search"))
        temperature = _clamp_float(form.get("temperature"), 1.0, 0.0, 1.0)
        top_p = _clamp_float(form.get("top_p"), 0.95, 0.01, 1.0)
        max_tokens = _clamp_int(form.get("max_tokens"), 4096, 1, 131072)

        thinking_raw = form.get("thinking")
        thinking: Optional[Dict[str, Any]] = None
        if thinking_raw:
            if isinstance(thinking_raw, str):
                try:
                    thinking = json.loads(thinking_raw)
                except Exception:
                    thinking = {"type": str(thinking_raw).strip()}
            elif isinstance(thinking_raw, dict):
                thinking = thinking_raw

        messages_raw = form.get("messages")
        history_raw = form.get("history")
        messages: List[Dict[str, Any]] = []
        if messages_raw:
            if isinstance(messages_raw, str):
                try:
                    messages = _normalize_messages(json.loads(messages_raw))
                except Exception:
                    raise HTTPException(status_code=400, detail="Invalid messages JSON")
            elif isinstance(messages_raw, list):
                messages = _normalize_messages(messages_raw)
        elif history_raw:
            if isinstance(history_raw, str):
                try:
                    messages = _normalize_messages(json.loads(history_raw))
                except Exception:
                    raise HTTPException(status_code=400, detail="Invalid history JSON")

        user_text = form.get("message")
        if user_text is None:
            user_text = form.get("text")
        user_text = str(user_text or "")

        uploads_any = form.getlist("files")
        if not uploads_any:
            uploads_any = form.getlist("file")
        uploads: List[UploadFile] = [u for u in uploads_any if isinstance(u, UploadFile)]

        total_bytes = 0
        extracted_file_texts: List[Tuple[str, str]] = []
        images_data_urls: List[Tuple[str, str]] = []

        for up in uploads:
            data = await _read_upload_bytes(up, MAX_SINGLE_UPLOAD_BYTES)
            total_bytes += len(data)
            if total_bytes > MAX_TOTAL_UPLOAD_BYTES:
                raise HTTPException(status_code=413, detail="Total upload too large")
            mime = _guess_mime(up.filename or "", up.content_type)
            name = up.filename or "file"

            if mime.startswith("image/"):
                b64 = base64.b64encode(data).decode("ascii")
                data_url = f"data:{mime};base64,{b64}"
                images_data_urls.append((name, data_url))
                continue

            extracted = ""
            if mime in ("application/pdf",):
                extracted = _extract_pdf_text(data)
            elif mime in (
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            ):
                extracted = _extract_docx_text(data)
            elif mime.startswith("text/") or mime in (
                "application/json",
                "application/xml",
                "application/x-yaml",
                "text/yaml",
                "application/yaml",
                "text/markdown",
            ):
                extracted = _safe_decode_text(data)
            else:
                extracted = ""

            extracted = _truncate_text(extracted or "", MAX_EXTRACTED_TEXT_CHARS)
            if extracted.strip():
                extracted_file_texts.append((name, extracted))

        requested_model = model
        chosen_model = requested_model
        if images_data_urls:
            chosen_model = DEFAULT_VISION_MODEL

        content = _build_user_content_with_attachments(user_text, extracted_file_texts, images_data_urls)

        if content:
            messages = messages + [{"role": "user", "content": content}]

        if not messages:
            raise HTTPException(status_code=400, detail="No messages provided")

        payload: Dict[str, Any] = {
            "model": chosen_model,
            "messages": messages,
            "temperature": temperature,
            "top_p": top_p,
            "max_tokens": max_tokens,
        }

        if thinking:
            payload["thinking"] = thinking

        if web_search:
            q = _last_user_text(messages).strip()
            if q:
                payload["tools"] = [
                    {
                        "type": "web_search",
                        "web_search": {
                            "search_query": q,
                            "search_result": True,
                        },
                    }
                ]
                payload["tool_choice"] = "auto"

        if stream:
            payload["stream"] = True

        return payload, stream

    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid JSON")

    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="JSON body must be an object")

    payload: Dict[str, Any] = dict(body)
    model = str(payload.get("model") or DEFAULT_TEXT_MODEL).strip() or DEFAULT_TEXT_MODEL
    payload["model"] = model
    messages = _normalize_messages(payload.get("messages"))
    if not messages:
        raise HTTPException(status_code=400, detail="messages missing or empty")
    payload["messages"] = messages

    if "temperature" in payload:
        payload["temperature"] = _clamp_float(payload.get("temperature"), 1.0, 0.0, 1.0)
