    if "top_p" in payload:
        payload["top_p"] = _clamp_float(payload.get("top_p"), 0.95, 0.01, 1.0)
    else:
        payload["top_p"] = 0.95

    if "max_tokens" in payload:
        payload["max_tokens"] = _clamp_int(payload.get("max_tokens"), 4096, 1, 131072)
    else:
        payload["max_tokens"] = 4096

    stream = _as_bool(payload.get("stream"))
    if stream:
        payload["stream"] = True
    else:
