def generate_chat_stream(create_kwargs: Dict[str, Any], session_id: Optional[str]) -> Iterator[str]:
    full_response_parts: List[str] = []
    start_time = time.time()
    token_count = 0

    try:
        create_kwargs["stream"] = True
        response_stream = openai_client.chat.completions.create(**create_kwargs)

        yield f"data: {json.dumps({'type': 'start', 'model': create_kwargs['model']})}\n\n"

        for chunk in response_stream:
            if not chunk.choices:
                continue

            delta = chunk.choices[0].delta
            content = delta.content

            if content is not None:
                full_response_parts.append(content)
                token_count += 1
                payload = {
                    "type": "content",
                    "content": content,
                    "done": False
                }
                yield f"data: {json.dumps(payload)}\n\n"

        full_text = "".join(full_response_parts)

        if session_id:
            try:
                session_manager.add_message(session_id, "assistant", full_text)
            except AppError:
                logger.error(f"Failed to save assistant response to session {session_id}")

        elapsed_time = time.time() - start_time
        yield f"data: {json.dumps({'type': 'done', 'content': '', 'done': True, 'metrics': {'tokens': token_count, 'elapsed_time_sec': elapsed_time}})}\n\n"

    except RateLimitError as e:
        logger.error(f"RateLimitError during streaming: {e}")
        yield f"data: {json.dumps({'type': 'error', 'error': 'Rate limit exceeded by provider.', 'code': 429, 'done': True})}\n\n"
    except AuthenticationError as e:
        logger.error(f"AuthenticationError during streaming: {e}")
        yield f"data: {json.dumps({'type': 'error', 'error': 'Authentication failed with provider.', 'code': 401, 'done': True})}\n\n"
    except APIConnectionError as e:
        logger.error(f"APIConnectionError during streaming: {e}")
        yield f"data: {json.dumps({'type': 'error', 'error': 'Upstream connection error.', 'code': 502, 'done': True})}\n\n"
    except APIError as e:
        logger.error(f"APIError during streaming: {e}")
        yield f"data: {json.dumps({'type': 'error', 'error': 'Upstream API error.', 'code': 500, 'done': True})}\n\n"
    except Exception as e:
        logger.exception(f"Unexpected error during streaming: {e}")
        yield f"data: {json.dumps({'type': 'error', 'error': 'Internal server error during generation.', 'code': 500, 'done': True})}\n\n"

@app.route('/api/chat', methods=['POST'])
