        top_p = max(0.0, min(1.0, float(data.get('top_p', 0.9))))
        max_tokens = max(1, min(128000, int(data.get('max_tokens', 8192))))
        presence_penalty = max(-2.0, min(2.0, float(data.get('presence_penalty', 0.0))))
        frequency_penalty = max(-2.0, min(2.0, float(data.get('frequency_penalty', 0.0))))
    except ValueError as e:
        raise AppError(f"Invalid numeric parameter: {str(e)}", 400)

    thinking_enabled = bool(data.get('thinking', False))

    messages_payload: List[Dict[str, str]] = []

    if session_id:
        session = session_manager.get_session(session_id)
        if not session:
            raise AppError("Session not found", 404)

        if user_message:
            session_manager.add_message(session_id, "user", user_message)

        with session.lock:
            messages_payload.append({"role": "system", "content": session.system_prompt})
            messages_payload.extend(session.messages)
    else:
        raw_messages = data.get('messages', [])
        if not isinstance(raw_messages, list):
            raise AppError("messages must be a list", 400)

        system_prompt = data.get('system_prompt', 'You are a helpful assistant.')
        messages_payload.append({"role": "system", "content": system_prompt})

        for msg in raw_messages:
            if not isinstance(msg, dict) or 'role' not in msg or 'content' not in msg:
                raise AppError("Invalid message format in messages array", 400)
            messages_payload.append({"role": str(msg['role']), "content": str(msg['content'])})

        if user_message:
            messages_payload.append({"role": "user", "content": str(user_message)})

    if not any(m["role"] == "user" for m in messages_payload):
        raise AppError("A user message is required to initiate generation", 400)

    thinking_config = {"type": "enabled"} if thinking_enabled else {"type": "disabled"}

    create_kwargs: Dict[str, Any] = {
        "model": "glm-5",
        "messages": messages_payload,
        "temperature": temperature,
        "top_p": top_p,
        "max_tokens": max_tokens,
        "presence_penalty": presence_penalty,
        "frequency_penalty": frequency_penalty,
        "extra_body": {"thinking": thinking_config}
    }

    if do_stream:
        return Response(
            stream_with_context(generate_chat_stream(create_kwargs, session_id)),
            mimetype='text/event-stream',
            headers={
                'Cache-Control': 'no-cache, no-transform',
                'X-Accel-Buffering': 'no',
                'Connection': 'keep-alive',
                'Content-Type': 'text/event-stream; charset=utf-8'
            }
        )
    else:
        try:
            create_kwargs["stream"] = False
            response = openai_client.chat.completions.create(**create_kwargs)

            if not response.choices:
                raise AppError("No choices returned from provider", 500)

            assistant_content = response.choices[0].message.content or ""

            if session_id:
                session_manager.add_message(session_id, "assistant", assistant_content)

            return jsonify({
                "status": "success",
                "data": {
                    "type": "complete",
                    "content": assistant_content,
                    "model": response.model,
                    "usage": {
                        "prompt_tokens": getattr(response.usage, 'prompt_tokens', 0),
                        "completion_tokens": getattr(response.usage, 'completion_tokens', 0),
                        "total_tokens": getattr(response.usage, 'total_tokens', 0)
                    },
                    "finish_reason": response.choices[0].finish_reason
                }
            })

        except RateLimitError:
            raise AppError("Rate limit exceeded by provider", 429)
        except AuthenticationError:
            raise AppError("Provider authentication failed", 401)
        except APIConnectionError:
            raise AppError("Upstream connection error", 502)
        except APIError as e:
            raise AppError(f"Provider API error: {str(e)}", 500)
        except Exception as e:
            logger.exception("Unexpected error in synchronous chat")
            raise AppError("Internal server error during chat completion", 500)

@app.route('/api/chat', methods=['OPTIONS'])
def chat_options_endpoint() -> Response:
    response = make_response()
    response.status_code = 204
    response.headers['Access-Control-Allow-Origin'] = request.headers.get('Origin', '*')
    response.headers['Access-Control-Allow-Methods'] = 'POST, OPTIONS'
    response.headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization, X-Request-ID'
    response.headers['Access-Control-Max-Age'] = '86400'
    return response

def shutdown_handler(signum: int, frame: Any) -> None:
    logger.info(f"Received shutdown signal {signum}. Initiating graceful shutdown...")
    session_manager.shutdown()
    sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, shutdown_handler)
    signal.signal(signal.SIGTERM, shutdown_handler)

    app.start_time = time.time()

    try:
        port = int(os.environ.get("PORT", 5000))
        host = os.environ.get("HOST", "0.0.0.0")
        debug_mode = os.environ.get("FLASK_DEBUG", "0") == "1"

        logger.info(f"Starting GLM-5 Backend API Server on {host}:{port} (Debug: {debug_mode})")
        app.run(host=host, port=port, debug=debug_mode, threaded=True, use_reloader=False)

    except Exception as e:
        logger.critical(f"Failed to start server: {e}")
        sys.exit(1)
